CREATE TABLE "media_files" ("id" TEXT PRIMARY KEY, "scope" TEXT NOT NULL, "message" TEXT NOT NULL, "checksum" TEXT NOT NULL, "size" INTEGER NOT NULL, "payload" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expires" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "media_files_scope_checksum_key" ON "media_files"("scope","checksum");
CREATE INDEX "media_files_scope_created_idx" ON "media_files"("scope","created");
CREATE INDEX "media_files_expires_idx" ON "media_files"("expires");
CREATE TABLE "media_processing_jobs" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "media_processing_jobs_fileId_idx" ON "media_processing_jobs"("fileId");
CREATE TABLE "media_extractions" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "media_extractions_fileId_idx" ON "media_extractions"("fileId");
CREATE TABLE "media_transcripts" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "media_transcripts_fileId_idx" ON "media_transcripts"("fileId");
CREATE TABLE "media_frames" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "media_frames_fileId_idx" ON "media_frames"("fileId");
CREATE TABLE "document_chunks" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "document_chunks_fileId_idx" ON "document_chunks"("fileId");
CREATE TABLE "file_delivery_history" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "file_delivery_history_fileId_idx" ON "file_delivery_history"("fileId");
CREATE TABLE "file_access_permissions" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "file_access_permissions_fileId_idx" ON "file_access_permissions"("fileId");
CREATE TABLE "file_feedback" ("id" TEXT PRIMARY KEY, "fileId" TEXT NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE, "value" TEXT NOT NULL, "created" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "file_feedback_fileId_idx" ON "file_feedback"("fileId");
